import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import {
  chmodSync,
  linkSync,
  mkdtempSync,
  mkdirSync,
  readFileSync,
  realpathSync,
  rmSync,
  statSync,
  symlinkSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import test from "node:test";
import { gunzipSync } from "node:zlib";

import stableStringify from "fast-json-stable-stringify";

import {
  assertPreparedLiteLearningExternalEvidenceArchivePinned,
  closePreparedLiteLearningExternalEvidenceArchive,
  inspectPreparedLiteLearningExternalEvidenceArchive,
  prepareLiteLearningExternalEvidenceArchive,
  type PreparedLiteLearningExternalEvidenceArchive,
} from "../../packages/aionis-learning-authority/src/store/lite-learning-external-evidence-archive-reader.js";

const FIXTURE_GZIP_BASE64 = "";

type Fixture = Readonly<{ archive: Buffer; publicRunAuthority: Buffer }>;
type RepositoryFixture = Readonly<{
  directory: string;
  archivePath: string;
  publicRunAuthorityPath: string;
  bundleCommitId: string;
}>;

const GIT_ENV = {
  LANG: "C",
  LC_ALL: "C",
  PATH: "/usr/bin:/bin",
  GIT_CONFIG_NOSYSTEM: "1",
  GIT_CONFIG_GLOBAL: "/dev/null",
  GIT_TERMINAL_PROMPT: "0",
} as const;

function fixture(): Fixture {
  const decoded = JSON.parse(gunzipSync(
    Buffer.from(FIXTURE_GZIP_BASE64, "base64"),
  ).toString("utf8")) as Readonly<{ archive: string; public: string }>;
  return Object.freeze({
    archive: Buffer.from(decoded.archive, "base64"),
    publicRunAuthority: Buffer.from(decoded.public, "base64"),
  });
}

function git(directory: string, args: readonly string[]): string {
  const result = spawnSync(
    "/usr/bin/git",
    ["--literal-pathspecs", "-C", directory, ...args],
    {
      encoding: "utf8",
      env: GIT_ENV,
      maxBuffer: 128 * 1024,
      shell: false,
      stdio: ["ignore", "pipe", "pipe"],
      timeout: 5_000,
    },
  );
  assert.ifError(result.error);
  assert.equal(result.signal, null);
  assert.equal(result.status, 0, result.stderr);
  assert.equal(result.stderr, "");
  return result.stdout.trim();
}

function temporaryDirectory(label: string): string {
  return realpathSync.native(mkdtempSync(join(tmpdir(), `aionis-${label}-`)));
}

function writePrivateFile(path: string, bytes: Uint8Array): void {
  mkdirSync(dirname(path), { recursive: true, mode: 0o700 });
  writeFileSync(path, bytes, { mode: 0o600 });
  chmodSync(path, 0o600);
}

function commitAll(directory: string, message: string): string {
  git(directory, ["add", "--all"]);
  git(directory, [
    "-c",
    "user.name=Aionis CI",
    "-c",
    "user.email=aionis-ci@example.invalid",
    "commit",
    "--quiet",
    "--no-gpg-sign",
    "-m",
    message,
  ]);
  return git(directory, ["rev-parse", "--verify", "HEAD^{commit}"]);
}

function populateRepository(
  directory: string,
  contents = fixture(),
): RepositoryFixture {
  const archivePath = join(directory, "evidence", "run-bundle.aionis-archive");
  const publicRunAuthorityPath = join(
    directory,
    "evidence",
    "public-run-authority.json",
  );
  writePrivateFile(archivePath, contents.archive);
  writePrivateFile(publicRunAuthorityPath, contents.publicRunAuthority);
  const bundleCommitId = commitAll(directory, "add external evidence bundle");
  return Object.freeze({
    directory,
    archivePath,
    publicRunAuthorityPath,
    bundleCommitId,
  });
}

function createRepository(label: string, contents = fixture()): RepositoryFixture {
  const directory = temporaryDirectory(label);
  git(directory, ["init", "--quiet", "--template="]);
  return populateRepository(directory, contents);
}

function prepare(repository: RepositoryFixture) {
  return prepareLiteLearningExternalEvidenceArchive({
    archivePath: repository.archivePath,
    publicRunAuthorityPath: repository.publicRunAuthorityPath,
  });
}

function cleanup(directory: string): void {
  rmSync(directory, { recursive: true, force: true });
}

test("prepared archive pins real Git blobs and keeps the stable bundle commit after unrelated HEAD advances", () => {
  const repository = createRepository("git-stable");
  let prepared: PreparedLiteLearningExternalEvidenceArchive | null = null;
  try {
    writePrivateFile(join(repository.directory, "UNRELATED.txt"), Buffer.from("later\n"));
    const verifiedHead = commitAll(repository.directory, "unrelated head advance");
    assert.notEqual(verifiedHead, repository.bundleCommitId);

    prepared = prepare(repository);
    const inspected = inspectPreparedLiteLearningExternalEvidenceArchive(prepared);
    assert.equal(inspected.tracking.bundle_commit_id, repository.bundleCommitId);
    assert.equal(inspected.tracking.verified_head_commit_id, verifiedHead);
    assert.equal(inspected.tracking.archive_repo_relative_path,
      "evidence/run-bundle.aionis-archive");
    assert.equal(inspected.tracking.public_run_authority_repo_relative_path,
      "evidence/public-run-authority.json");
    assert.equal(inspected.tracking.raw_archive_byte_length,
      readFileSync(repository.archivePath).byteLength);
    assert.equal(inspected.tracking.public_run_authority_byte_length,
      readFileSync(repository.publicRunAuthorityPath).byteLength);
    assert.equal(inspected.archiveValidation.rawArchiveSha256,
      inspected.tracking.raw_archive_sha256);
    assert.equal(Object.isFrozen(inspected), true);
    assert.equal(Object.isFrozen(inspected.tracking), true);
    assert.equal(Object.isFrozen(inspected.archiveValidation.contracts), true);
    assert.doesNotThrow(() => (
      assertPreparedLiteLearningExternalEvidenceArchivePinned(prepared!)
    ));

    writePrivateFile(join(repository.directory, "ANOTHER.txt"), Buffer.from("new head\n"));
    commitAll(repository.directory, "advance head after preparation");
    assert.throws(
      () => assertPreparedLiteLearningExternalEvidenceArchivePinned(prepared!),
      /git_head_changed/u,
    );
    assert.doesNotThrow(() => assertPreparedLiteLearningExternalEvidenceArchivePinned(
      prepared!,
      { verifyHead: false },
    ));
  } finally {
    if (prepared) closePreparedLiteLearningExternalEvidenceArchive(prepared);
    cleanup(repository.directory);
  }
});

test("reader rejects dirty and untracked Git inputs from real repositories", () => {
  const dirty = createRepository("git-dirty");
  try {
    writeFileSync(dirty.archivePath, Buffer.concat([
      readFileSync(dirty.archivePath),
      Buffer.from([0]),
    ]));
    assert.throws(() => prepare(dirty), /worktree_bytes_do_not_match_head|archive_/u);
  } finally {
    cleanup(dirty.directory);
  }

  const untrackedDirectory = temporaryDirectory("git-untracked");
  try {
    git(untrackedDirectory, ["init", "--quiet", "--template="]);
    writePrivateFile(join(untrackedDirectory, "tracked.txt"), Buffer.from("tracked\n"));
    commitAll(untrackedDirectory, "tracked baseline");
    const contents = fixture();
    const untracked: RepositoryFixture = {
      directory: untrackedDirectory,
      archivePath: join(untrackedDirectory, "evidence", "bundle.archive"),
      publicRunAuthorityPath: join(untrackedDirectory, "evidence", "public.json"),
      bundleCommitId: "",
    };
    writePrivateFile(untracked.archivePath, contents.archive);
    writePrivateFile(untracked.publicRunAuthorityPath, contents.publicRunAuthority);
    assert.throws(() => prepare(untracked), /git_tree_entry_missing/u);
  } finally {
    cleanup(untrackedDirectory);
  }
});

test("reader rejects symlink, hard-link, executable, and group-writable evidence files", () => {
  const repository = createRepository("filesystem-boundary");
  try {
    const aliasDirectory = join(repository.directory, "alias");
    symlinkSync(join(repository.directory, "evidence"), aliasDirectory, "dir");
    assert.throws(
      () => prepareLiteLearningExternalEvidenceArchive({
        archivePath: join(aliasDirectory, "run-bundle.aionis-archive"),
        publicRunAuthorityPath: repository.publicRunAuthorityPath,
      }),
      /symlink_rejected|noncanonical_path/u,
    );

    const hardLinkPath = join(repository.directory, "archive-hard-link");
    linkSync(repository.archivePath, hardLinkPath);
    assert.throws(() => prepare(repository), /hard_link_rejected/u);
    rmSync(hardLinkPath);

    chmodSync(repository.archivePath, 0o700);
    assert.throws(() => prepare(repository), /executable_data_file/u);
    chmodSync(repository.archivePath, 0o620);
    assert.throws(() => prepare(repository), /group_or_other_writable/u);
    chmodSync(repository.archivePath, 0o600);
  } finally {
    cleanup(repository.directory);
  }
});

test("reader rejects group/other write authority on the worktree and Git control paths", () => {
  const repository = createRepository("git-control-mode");
  try {
    const gitDirectory = git(repository.directory, [
      "rev-parse",
      "--path-format=absolute",
      "--git-dir",
    ]);
    const targets = [
      repository.directory,
      join(gitDirectory, "HEAD"),
      join(gitDirectory, "refs"),
      join(gitDirectory, "objects"),
    ] as const;
    for (const target of targets) {
      const originalMode = statSync(target).mode & 0o7777;
      try {
        chmodSync(target, originalMode | 0o020);
        assert.throws(
          () => prepare(repository),
          /git_filesystem_untrusted:group_or_other_writable/u,
        );
      } finally {
        chmodSync(target, originalMode);
      }
    }
  } finally {
    cleanup(repository.directory);
  }
});

test("reader rejects local Git include and includeIf directives outside the trust tree", () => {
  const repository = createRepository("git-config-include");
  const externalDirectory = temporaryDirectory("git-external-config");
  const externalConfig = join(externalDirectory, "delegated.gitconfig");
  try {
    writePrivateFile(externalConfig, Buffer.from("[core]\n\tfilemode = true\n"));
    git(repository.directory, ["config", "--add", "include.path", externalConfig]);
    assert.throws(
      () => prepare(repository),
      /git_filesystem_untrusted:git_local_config_include_rejected/u,
    );

    git(repository.directory, ["config", "--unset-all", "include.path"]);
    git(repository.directory, [
      "config",
      "--add",
      "includeIf.gitdir:/definitely-not-this-repository/**.path",
      externalConfig,
    ]);
    assert.throws(
      () => prepare(repository),
      /git_filesystem_untrusted:git_local_config_include_rejected/u,
    );
  } finally {
    cleanup(externalDirectory);
    cleanup(repository.directory);
  }
});

test("reader verifies linked-worktree git-dir and common-dir trust boundaries", {
  timeout: 30_000,
}, () => {
  const main = createRepository("linked-main");
  const linkedDirectory = temporaryDirectory("linked-worktree");
  let prepared: PreparedLiteLearningExternalEvidenceArchive | null = null;
  try {
    git(main.directory, [
      "worktree",
      "add",
      "--quiet",
      "--detach",
      linkedDirectory,
      "HEAD",
    ]);
    const linked: RepositoryFixture = Object.freeze({
      directory: linkedDirectory,
      archivePath: join(
        linkedDirectory,
        "evidence",
        "run-bundle.aionis-archive",
      ),
      publicRunAuthorityPath: join(
        linkedDirectory,
        "evidence",
        "public-run-authority.json",
      ),
      bundleCommitId: main.bundleCommitId,
    });
    prepared = prepare(linked);
    assert.equal(
      inspectPreparedLiteLearningExternalEvidenceArchive(prepared)
        .tracking.bundle_commit_id,
      main.bundleCommitId,
    );
    closePreparedLiteLearningExternalEvidenceArchive(prepared);
    prepared = null;

    const commonObjects = git(linkedDirectory, [
      "rev-parse",
      "--path-format=absolute",
      "--git-path",
      "objects",
    ]);
    const originalMode = statSync(commonObjects).mode & 0o7777;
    try {
      chmodSync(commonObjects, originalMode | 0o020);
      assert.throws(
        () => prepare(linked),
        /git_filesystem_untrusted:group_or_other_writable/u,
      );
    } finally {
      chmodSync(commonObjects, originalMode);
    }
  } finally {
    if (prepared) closePreparedLiteLearningExternalEvidenceArchive(prepared);
    cleanup(linkedDirectory);
    cleanup(main.directory);
  }
});

test("reader rejects delegated filesystem ACLs on Git object storage", {
  skip: process.platform !== "darwin" && process.platform !== "linux",
  timeout: 30_000,
}, (t) => {
  const repository = createRepository("git-control-acl");
  const objectsPath = git(repository.directory, [
    "rev-parse",
    "--path-format=absolute",
    "--git-path",
    "objects",
  ]);
  let aclInstalled = false;
  try {
    const serviceUid = typeof process.getuid === "function" ? process.getuid() : -1;
    const delegatedUid = serviceUid === 65_534 ? 65_533 : 65_534;
    const addAcl = process.platform === "darwin"
      ? spawnSync(
        "/bin/chmod",
        ["+a", "everyone allow write", objectsPath],
        { encoding: "utf8", timeout: 5_000 },
      )
      : spawnSync(
        "/usr/bin/setfacl",
        ["-m", `u:${String(delegatedUid)}:r--`, objectsPath],
        { encoding: "utf8", timeout: 5_000 },
      );
    if (addAcl.error || addAcl.status !== 0) {
      t.skip(`filesystem ACL setup unavailable: ${addAcl.error?.message ?? addAcl.stderr}`);
      return;
    }
    aclInstalled = true;
    assert.equal(statSync(objectsPath).mode & 0o022, 0);
    assert.throws(
      () => prepare(repository),
      /git_filesystem_untrusted:delegated_or_unverifiable_(?:darwin|linux)_acl/u,
    );
  } finally {
    if (aclInstalled) {
      if (process.platform === "darwin") {
        spawnSync("/bin/chmod", ["-N", objectsPath], { timeout: 5_000 });
      } else {
        spawnSync("/usr/bin/setfacl", ["-b", objectsPath], { timeout: 5_000 });
      }
    }
    cleanup(repository.directory);
  }
});

test("reader computes and verifies native Git blob IDs in a SHA-256 repository", {
  timeout: 30_000,
}, (t) => {
  const directory = temporaryDirectory("git-sha256");
  let prepared: PreparedLiteLearningExternalEvidenceArchive | null = null;
  try {
    const initialized = spawnSync(
      "/usr/bin/git",
      [
        "--literal-pathspecs",
        "-C",
        directory,
        "init",
        "--quiet",
        "--object-format=sha256",
      ],
      {
        encoding: "utf8",
        env: GIT_ENV,
        maxBuffer: 128 * 1024,
        shell: false,
        stdio: ["ignore", "pipe", "pipe"],
        timeout: 5_000,
      },
    );
    if (initialized.error || initialized.status !== 0) {
      t.skip(`Git SHA-256 repository unavailable: ${initialized.error?.message ?? initialized.stderr}`);
      return;
    }
    const repository = populateRepository(directory);
    prepared = prepare(repository);
    const tracking = inspectPreparedLiteLearningExternalEvidenceArchive(prepared)
      .tracking;
    assert.equal(tracking.object_format, "sha256");
    assert.match(tracking.verified_head_commit_id, /^[0-9a-f]{64}$/u);
    assert.match(tracking.bundle_commit_id, /^[0-9a-f]{64}$/u);
    assert.match(tracking.archive_blob_oid, /^[0-9a-f]{64}$/u);
    assert.match(tracking.public_run_authority_blob_oid, /^[0-9a-f]{64}$/u);
  } finally {
    if (prepared) closePreparedLiteLearningExternalEvidenceArchive(prepared);
    cleanup(directory);
  }
});

test("reader rejects a separately committed canonical public authority that differs from the archive member", () => {
  const contents = fixture();
  const changed = JSON.parse(contents.publicRunAuthority.toString("utf8")) as {
    terminal_fact_drain_receipt: { signature_base64: string };
  };
  const signature = changed.terminal_fact_drain_receipt.signature_base64;
  changed.terminal_fact_drain_receipt.signature_base64 =
    `${signature[0] === "A" ? "B" : "A"}${signature.slice(1)}`;
  const mismatchedPublic = Buffer.from(stableStringify(changed), "utf8");
  const repository = createRepository("public-mismatch", {
    archive: contents.archive,
    publicRunAuthority: mismatchedPublic,
  });
  try {
    assert.throws(() => prepare(repository), /public_run_authority_archive_mismatch/u);
  } finally {
    cleanup(repository.directory);
  }
});

test("FIFO input is rejected without a blocking open", () => {
  const directory = temporaryDirectory("fifo");
  try {
    const fifoPath = join(directory, "archive.fifo");
    const made = spawnSync("/usr/bin/mkfifo", [fifoPath], {
      encoding: "utf8",
      env: GIT_ENV,
      maxBuffer: 64 * 1024,
      shell: false,
      timeout: 5_000,
    });
    assert.ifError(made.error);
    assert.equal(made.status, 0, made.stderr);
    const publicPath = join(directory, "public.json");
    writePrivateFile(publicPath, Buffer.from("{}"));
    const startedAt = Date.now();
    assert.throws(
      () => prepareLiteLearningExternalEvidenceArchive({
        archivePath: fifoPath,
        publicRunAuthorityPath: publicPath,
      }),
      /archive_regular_file_required/u,
    );
    assert.ok(Date.now() - startedAt < 1_000);
  } finally {
    cleanup(directory);
  }
});

test("prepared capability is module-owned and cannot be reused after descriptor close", () => {
  const repository = createRepository("capability");
  try {
    const forged = Object.freeze(Object.create(null)) as
      PreparedLiteLearningExternalEvidenceArchive;
    assert.throws(
      () => inspectPreparedLiteLearningExternalEvidenceArchive(forged),
      /unrecognized_prepared_capability/u,
    );
    assert.throws(
      () => assertPreparedLiteLearningExternalEvidenceArchivePinned(forged),
      /unrecognized_prepared_capability/u,
    );
    assert.throws(
      () => closePreparedLiteLearningExternalEvidenceArchive(forged),
      /unrecognized_prepared_capability/u,
    );

    const prepared = prepare(repository);
    assert.doesNotThrow(() => inspectPreparedLiteLearningExternalEvidenceArchive(prepared));
    closePreparedLiteLearningExternalEvidenceArchive(prepared);
    assert.doesNotThrow(() => closePreparedLiteLearningExternalEvidenceArchive(prepared));
    assert.throws(
      () => inspectPreparedLiteLearningExternalEvidenceArchive(prepared),
      /prepared_capability_closed/u,
    );
    assert.throws(
      () => assertPreparedLiteLearningExternalEvidenceArchivePinned(prepared),
      /prepared_capability_closed/u,
    );
  } finally {
    cleanup(repository.directory);
  }
});
